from dotenv import find_dotenv, load_dotenv

from extracao.constants import (
    AGG_LICENCIAMENTO,
    COLS_STEL,
    DICT_LICENCIAMENTO,
    MONGO_TELECOM,
    PROJECTION_LICENCIAMENTO,
)

from .mosaico import Mosaico

# %% ../../nbs/01f_telecom.ipynb #69f77676
load_dotenv(find_dotenv())

# %% ../../nbs/01f_telecom.ipynb #5c1c8f81
MONGO_URI = os.environ.get("MONGO_URI")


# %% ../../nbs/01f_telecom.ipynb #ac467088
class Telecom(Mosaico):
    """Extração e Processamento dos serviços de Telecomunições distintos de SMP"""

    def __init__(
        self,
        mongo_uri: str = MONGO_URI,
        limit: int = 0,
        read_cache: bool = False,
        full: bool = False,
    ) -> None:
        super().__init__(mongo_uri, read_cache=read_cache)
        self.limit = limit
        self.full = full

    @property
    def stem(self):
        return "telecom"

    @property
    def output_stem(self):
        return f"{self.stem}_full" if self.full else self.stem

    @property
    def collection(self):
        return "licenciamento"

    @property
    def query(self):
        return MONGO_TELECOM

    @property
    def projection(self):
        return PROJECTION_LICENCIAMENTO

    @property
    def columns(self):
        return COLS_STEL

    @property
    def cols_mapping(self):
        return DICT_LICENCIAMENTO

    def extraction(self) -> pd.DataFrame:
        pipeline = [{"$match": self.query}, {"$project": self.projection}]
        if self.limit > 0:
            pipeline.append({"$limit": self.limit})
        df = self._extract(self.collection, pipeline)
        df["Log"] = ""
        return df

    def _format(
        self,
        df: pd.DataFrame,  # DataFrame com os dados de Estações e Plano_Básico mesclados
    ) -> pd.DataFrame:  # DataFrame com os dados mesclados e limpos
        """Clean the merged dataframe with the data from the MOSAICO page"""
        df = df.rename(columns=self.cols_mapping)
        df = self.split_designacao(df)
        if self.full:
            df_sub = self.ungrouped(df)
            columns = [column for column in self.columns if column != "Multiplicidade"]
        else:
            df_sub = self.aggregate(
                df, AGG_LICENCIAMENTO, "MOSAICO-TELECOM: Agrupamento"
            )
            columns = self.columns
        df_sub["Fonte"] = "MOSAICO-LICENCIAMENTO"
        return df_sub.loc[:, columns]
